# Inputs are constructed within the stated limits and preserve problem-specific invariants.
import random


def generate(seed: int = 0) -> list[str]:
    r = random.Random(seed)
    vals = set()
    while len(vals) < 600:
        n = r.randint(1, 100)
        a = "".join(r.choice("xy") for _ in range(n))
        b = "".join(r.choice("xy") for _ in range(n))
        vals.add((a, b))
    calls = [f"candidate(s1={a!r}, s2={b!r})" for a, b in vals]
    calls.append(
        "candidate(s1='', s2='')"
    )
    assert 500 <= len(calls) <= 999
    assert len(calls) == len(set(calls))
    return calls
